with cleaned as (select id, customer_id, account_type, balance, opened_date, status, round(balance, 2) as balance_rounded, coalesce(status, 'UNKNOWN') as status_filled from accounts where opened_date > to_date('2023-06-02') and status is not null) select c.segment, c.country, count(*) as num_rows, round(sum(a.balance), 2) as total_balance, avg(a.balance_rounded) as avg_balance_rounded from cleaned a left join customers c on a.customer_id = c.id group by grouping sets ((c.segment, c.country), (c.segment), ());
